  exit 1
fi

stage "Configure GitHub Actions operations"
say "Populate the exact repository variables and secrets referenced by .github/workflows/preprod.yml."
open_url "$REPO_URL/settings/variables/actions"
open_url "$REPO_URL/settings/secrets/actions"
open_url "$REPO_URL/actions/workflows/preprod.yml"
step "The workflow's randomness job must expose only SHROUDLY_GITHUB_ACTIONS_SEED, SHROUDLY_GITHUB_ACTIONS_AUTOMATION_ENDPOINT, and SHROUDLY_GITHUB_ACTIONS_AUTOMATION_TOKEN. Render and offline-maintainer credentials stay in their own isolated runners and are never copied into GitHub Actions."
if ! confirm "Has the workflow/script credential contract been reviewed so each runner receives only its contributor-scoped seed and endpoint/token?"; then
  warn "GitHub operations remain blocked until credential isolation is confirmed."
  exit 1
fi
note "The names below are copied exactly from the current workflow. Values are written only after the confirmation below; no wallet keys or non-GitHub contributor credentials are captured."
ask SHROUDLY_DEPLOYMENT_ID "Paste the immutable deployment ID for the Actions variable:"
require_value SHROUDLY_DEPLOYMENT_ID "$SHROUDLY_DEPLOYMENT_ID"
ask SHROUDLY_GITHUB_ACTIONS_AUTOMATION_ENDPOINT "Paste the HTTPS GitHub Actions automation endpoint for the Actions variable:"
require_https SHROUDLY_GITHUB_ACTIONS_AUTOMATION_ENDPOINT "$SHROUDLY_GITHUB_ACTIONS_AUTOMATION_ENDPOINT"
ask_secret BETTER_STACK_HEARTBEAT_URL "Paste the Better Stack heartbeat URL for the Actions secret:"
require_https BETTER_STACK_HEARTBEAT_URL "$BETTER_STACK_HEARTBEAT_URL"
ask_secret SHROUDLY_GITHUB_ACTIONS_SEED "Paste the isolated GitHub Actions contributor seed:"
require_value SHROUDLY_GITHUB_ACTIONS_SEED "$SHROUDLY_GITHUB_ACTIONS_SEED"
ask_secret SHROUDLY_GITHUB_ACTIONS_AUTOMATION_TOKEN "Paste the isolated GitHub Actions automation bearer token:"
require_value SHROUDLY_GITHUB_ACTIONS_AUTOMATION_TOKEN "$SHROUDLY_GITHUB_ACTIONS_AUTOMATION_TOKEN"
if ! confirm "Write the two GitHub Actions variables and three repository secrets now?"; then
  warn "GitHub values were not written; stopping before qualification."
  exit 1
fi
write_env BETTER_STACK_HEARTBEAT_URL "$BETTER_STACK_HEARTBEAT_URL"
write_env SHROUDLY_DEPLOYMENT_ID "$SHROUDLY_DEPLOYMENT_ID"
write_env SHROUDLY_GITHUB_ACTIONS_AUTOMATION_ENDPOINT "$SHROUDLY_GITHUB_ACTIONS_AUTOMATION_ENDPOINT"
set_var SHROUDLY_DEPLOYMENT_ID "$SHROUDLY_DEPLOYMENT_ID"
set_var SHROUDLY_GITHUB_ACTIONS_AUTOMATION_ENDPOINT "$SHROUDLY_GITHUB_ACTIONS_AUTOMATION_ENDPOINT"
set_secret BETTER_STACK_HEARTBEAT_URL "$BETTER_STACK_HEARTBEAT_URL"
set_secret SHROUDLY_GITHUB_ACTIONS_SEED "$SHROUDLY_GITHUB_ACTIONS_SEED"
set_secret SHROUDLY_GITHUB_ACTIONS_AUTOMATION_TOKEN "$SHROUDLY_GITHUB_ACTIONS_AUTOMATION_TOKEN"
note "GitHub Actions variables attempted: SHROUDLY_DEPLOYMENT_ID SHROUDLY_GITHUB_ACTIONS_AUTOMATION_ENDPOINT"

stage "Run Recovery Kit and Backup Account drills"
say "Prove recoverability before any qualifying contribution."
open_url "$REPO_URL/actions/workflows/preprod.yml"
open_url "https://vercel.com/dashboard"
note "Captured value: PREPROD_URL. Source: the live Vercel deployment. Destination: memory for this run only; it is not written to ENV_FILE, GitHub, or evidence."
ask PREPROD_URL "Paste the live Vercel Preprod URL for the drill:"
require_https PREPROD_URL "$PREPROD_URL"
open_url "$PREPROD_URL"
step "Export and restore a Recovery Kit for each participant wallet before its first contribution. Verify the restored wallet identity without exposing the kit to the wizard."
step "Run the Backup Account export/restore drill through the deployed app with the required AAL2 session. Confirm Supabase stores ciphertext only and retired/invalid restores are rejected."
step "Record only sanitized drill results and checksums in the protected evidence workspace."
pause "After both Recovery Kit and Backup Account drills pass, press Enter"
if ! confirm "Did Recovery Kit restore and Backup Account recovery pass with invalid/retired restore paths rejected?"; then
  warn "Recovery drills are not confirmed; stopping."
  exit 1
fi

stage "Perform the supported desktop Chrome/Lace transaction"
say "Use the genuine DApp Connector path from the public Vercel build."
open_url "$PREPROD_URL"
open_url "https://docs.midnight.network/api-reference/dapp-connector"
step "Use a supported desktop Chrome session with the correct Preprod Lace wallet. Do not use mobile or an unsupported browser for qualification."
step "Connect Lace, complete one minimal transaction from the public build, and record only the sanitized transaction reference."
step "Accept success only after network finality, indexer visibility, and a fresh ledger confirmation. Do not paste addresses, commitments, nullifiers, or private state here."
pause "After the Lace transaction is finalized and cross-checked, press Enter"
if ! confirm "Did the public build complete one genuine Lace transaction with finality, indexer, and ledger confirmation?"; then
  warn "Browser evidence is not confirmed; stopping."
  exit 1
fi

stage "Run the genuine five-wallet qualification draw"
say "Exercise the actual contribution, draw, and claim path with isolated wallets."
open_url "$PREPROD_URL"
open_url "$REPO_URL/issues/18"
step "Use four isolated setup wallets for qualifying contributions and the fifth as the primary browser wallet. Complete the real draw phases and deadlines."
step "Let the contract select the owner; the selected wallet alone may claim. Do not retry a winner, override selection, or substitute a deterministic fixture for this qualification."
step "For each transaction, retain only the required JSON flags: transactionId, networkFinalized, indexerVisible, ledgerConfirmed, deploymentId, and sourceRevision."
pause "After the five-wallet draw and selected-wallet claim have finalized, press Enter"
if ! confirm "Did the genuine five-wallet draw select an owner and allow only the selected wallet to claim?"; then
  warn "Five-wallet qualification is not confirmed; stopping."
  exit 1
fi

stage "Review and retain the sanitized evidence bundle"
say "Review evidence only after the qualification transactions are final and cross-checked."
open_url "$REPO_URL/actions/workflows/preprod.yml"
open_url "$REPO_URL/issues/18"
step "Dispatch the evidence operation only after health is green, then verify the bundle with scripts/verify-evidence.mjs."
step "Check that every transaction has finality, indexer, fresh-ledger, deployment, and source-revision fields. Scrub wallet addresses, commitments, nullifiers, backup IDs, private state, and secrets."
step "Retain the redacted/checksummed artifact in GitHub Actions for at least 90 days, and record the artifact/run reference in the release worksheet."
pause "After the evidence bundle is verified, redacted, checksummed, and retained, press Enter"
if ! confirm "Has the evidence review passed and is the 90-day Actions artifact retention confirmed?"; then
  warn "Evidence retention is not confirmed; stopping."
  exit 1
fi

stage "Complete governance handoff and remove temporary authority"
say "Perform the irreversible authority handoff only after all qualification evidence is accepted."
open_url "$REPO_URL/issues/18"
step "Use the approved two-of-three governance procedure to hand off operational authority, validate offline governance/emergency/randomness materials, and record only sanitized references."
step "Remove the Temporary Deployer Authority within 24 hours of final deployment. If removal cannot be finalized, lock submissions and follow the incident/governance procedure; never bypass the invariant."
warn "The repository does not define a human-safe handoff command. Use the reviewed protected operator procedure and verify the resulting state through finality, indexer, and ledger checks."
pause "After governance handoff and deployer removal have been finalized, press Enter"
if ! confirm "Is governance in control, are offline materials validated, and is Temporary Deployer Authority removed or the submission lock active?"; then
  warn "Governance handoff is not confirmed; stopping."
  exit 1
fi

stage "Create the immutable tag and GitHub Release"
say "Publish only after the release gates and evidence bundle have been reviewed."
open_url "$REPO_URL/issues/2"
open_url "$REPO_URL/issues/18"
open_url "$REPO_URL/releases/new"
step "Confirm the exact Compatibility Profile, source revision, deployment ID, four contract IDs/hashes, finalized evidence, provider approvals, and 90-day artifact retention."
step "Confirm Mainnet transactional entrypoints remain disabled and the published build is explicitly Preprod-only."
step "Create the immutable release tag and GitHub Release through the reviewed maintainer process, then close the completed human-gate child issues. Do not publish if any gate remains needs-info or ready-for-human."
pause "After the maintainer has created the immutable tag and GitHub Release, press Enter"
if ! confirm "Is the immutable release published with all human gates complete and Mainnet still disabled?"; then
  warn "Publication is not confirmed; stopping."
  exit 1
fi

finish
